example_solution:
package speed

// NewCar creates a new car with given specifications.
func NewCar(speed, batteryDrain int) Car {
	return Car{
		speed:        speed,
		batteryDrain: batteryDrain,
		battery:      100,
	}
}

// Car implements a remote controlled car.
type Car struct {
	speed        int
	batteryDrain int

	battery  int
	distance int
}

// Track implements a race track.
type Track struct {
	distance int
}

// NewTrack creates a new track with given distance.
func NewTrack(distance int) Track {
	return Track{
		distance: distance,
	}
}

// Drive drives the car one time. If there is not enough battery to drive one more time,
// the car will not move.
func Drive(car Car) Car {
	if car.battery < car.batteryDrain {
		return car
	}

	car.distance += car.speed
	car.battery -= car.batteryDrain
	return car
}

// CanFinish checks if a car is able to finish a certain track.
func CanFinish(car Car, track Track) bool {
	maxDistance := car.battery / car.batteryDrain * car.speed
	return track.distance <= maxDistance
}

test_code:
package speed

import "testing"

func TestNewCar(t *testing.T) {
	tests := []struct {
		name     string
		car      Car
		expected Car
	}{
		{
			name: "Create a new car.",
			car: Car{
				speed:        5,
				batteryDrain: 2,
				battery:      100,
			},
			expected: Car{
				speed:        5,
				batteryDrain: 2,
				battery:      100,
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := NewCar(tt.car.speed, tt.car.batteryDrain)

			if got != tt.expected {
				t.Errorf("NewCar(%+v,%+v) = %+v; expected %+v", tt.car.speed, tt.car.batteryDrain, got, tt.expected)
			}
		})
	}
}

func TestNewTrack(t *testing.T) {
	tests := []struct {
		name     string
		track    Track
		expected Track
	}{
		{
			name: "Create a long track.",
			track: Track{
				distance: 800,
			},
			expected: Track{
				distance: 800,
			},
		},
		{
			name: "Create a short track.",
			track: Track{
				distance: 360,
			},
			expected: Track{
				distance: 360,
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := NewTrack(tt.track.distance)

			if got != tt.expected {
				t.Errorf("NewTrack(%+v) = %+v; expected %+v", tt.track.distance, got, tt.expected)
			}
		})
	}
}

func TestDrive(t *testing.T) {
	tests := []struct {
		name     string
		car      Car
		expected Car
	}{
		{
			name: "Drive the car with full battery.",
			car: Car{
				speed:        5,
				batteryDrain: 2,
				battery:      100,
				distance:     0,
			},
			expected: Car{
				speed:        5,
				batteryDrain: 2,
				battery:      98,
				distance:     5,
			},
		},
		{
			name: "Drive the car with exactly enough battery.",
			car: Car{
				speed:        18,
				batteryDrain: 10,
				battery:      10,
				distance:     0,
			},
			expected: Car{
				speed:        18,
				batteryDrain: 10,
				battery:      0,
				distance:     18,
			},
		},
		{
			name: "Drive when battery percentage is below battery drain",
			car: Car{
				speed:        5,
				batteryDrain: 7,
				battery:      3,
				distance:     0,
			},
			expected: Car{
				speed:        5,
				batteryDrain: 7,
				battery:      3,
				distance:     0,
			},
		},
		{
			name: "Drive the car with battery drained.",
			car: Car{
				speed:        5,
				batteryDrain: 5,
				battery:      4,
				distance:     0,
			},
			expected: Car{
				speed:        5,
				batteryDrain: 5,
				battery:      4,
				distance:     0,
			},
		},
		{
			name: "Drive the car with positive initial distance and battery drained",
			car: Car{
				speed:        5,
				batteryDrain: 3,
				battery:      2,
				distance:     1,
			},
			expected: Car{
				speed:        5,
				batteryDrain: 3,
				battery:      2,
				distance:     1,
			},
		},
		{
			name: "Drive the car with positive initial distance and full battery",
			car: Car{
				speed:        5,
				batteryDrain: 3,
				battery:      100,
				distance:     1,
			},
			expected: Car{
				speed:        5,
				batteryDrain: 3,
				battery:      97,
				distance:     6,
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := Drive(tt.car)

			if got != tt.expected {
				t.Errorf("Drive(%+v) = %+v; expected %+v", tt.car, got, tt.expected)
			}
		})
	}
}

func TestCanFinish(t *testing.T) {
	tests := []struct {
		name     string
		car      Car
		track    Track
		expected bool
	}{
		{
			name: "Car can easily finish the track distance.",
			car: Car{
				speed:        5,
				batteryDrain: 2,
				battery:      100,
				distance:     20,
			},
			track: Track{
				distance: 30,
			},
			expected: true,
		},
		{
			name: "Car can finish the track distance just as the battery is drained.",
			car: Car{
				speed:        5,
				batteryDrain: 5,
				battery:      100,
				distance:     20,
			},
			track: Track{
				distance: 100,
			},
			expected: true,
		},
		{
			name: "Car cannot finish the track distance.",
			car: Car{
				speed:        2,
				batteryDrain: 6,
				battery:      100,
				distance:     5,
			},
			track: Track{
				distance: 80,
			},
			expected: false,
		},
		{
			name: "Car can finish the track distance with initial battery less than 100%",
			car: Car{
				speed:        2,
				batteryDrain: 3,
				battery:      25,
				distance:     0,
			},
			track: Track{
				distance: 16,
			},
			expected: true,
		},
		{
			name: "Car cannot finish the track distance with initial battery less than 100%",
			car: Car{
				speed:        2,
				batteryDrain: 3,
				battery:      25,
				distance:     0,
			},
			track: Track{
				distance: 24,
			},
			expected: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := CanFinish(tt.car, tt.track)

			if got != tt.expected {
				t.Errorf("CanFinish(%#v, %#v) = %+v; expected %+v", tt.car, tt.track, got, tt.expected)
			}
		})
	}
}
